"use client";

// Site-wide editable text.
// Small labels, buttons, card texts etc. that live in the components go through tx(key, default).
// If the text was changed in Sanity → "Website text", the edited version is shown instead.
// The list of keys is generated by scripts/text-manifest.mjs.

import React from "react";

let TEXT_MAP: Record<string, string> = {};

/** Returns the edited text for `key`, or the built-in text. */
export function tx(key: string, fallback: string): string {
  const v = TEXT_MAP[key];
  return typeof v === "string" && v.trim() !== "" ? v : fallback;
}

/** Same as tx() but as a component, for files that are not client components. */
export function Tx({ k, d }: { k: string; d: string }) {
  return <>{tx(k, d)}</>;
}

function setTextMap(value: Record<string, string>) {
  TEXT_MAP = value || {};
}

/** Sets the edited-text map before the page renders (server and browser). */
export function TextProvider({ value, children }: { value: Record<string, string>; children: React.ReactNode }) {
  setTextMap(value);
  return <>{children}</>;
}
